#include <stdexcept>
#include <vector>

class Scoreboard {
public:
    // Strong guarantee: on exception, scores_ is unchanged.
    void replace_all(const std::vector<int>& input) {
        std::vector<int> next;                      // build aside.
        next.reserve(input.size());                 // may throw: scores_ untouched.
        for (int s : input) {
            if (s < 0) throw std::invalid_argument("negative score");
            next.push_back(s);
        }
        scores_.swap(next);                         // commit: swap never throws.
    }
    std::size_t size() const noexcept { return scores_.size(); }   // no-throw.
private:
    std::vector<int> scores_;
};

int main() {
    Scoreboard b;
    try {
        b.replace_all({90, -5, 70});
    } catch (const std::invalid_argument& e) {      // catch by const reference.
        // b still holds its previous scores.
    }
}
```

